# The rims are close and the carried bowl is upright enough for a low nesting release.
# Lower the last three centimeters, open, retreat vertically, and return the right arm home for a clear stack check.
obs, count, outcome = servo_translate('right', [0.12, -0.27, 0.970], 0.0, max_steps=12)
print('lower', count, outcome)
ended = outcome == 'ended'
if outcome == 'reached':
    action = {k: list(obs['state'][k]) for k in ['left_ee_pose', 'right_ee_pose', 'left_ee_joint_state', 'right_ee_joint_state']}
    action['right_ee_joint_state'] = [0.8]
    for i in range(10):
        obs, reward, terminated, truncated, info = step(action)
        if terminated or truncated:
            ended = True
            break
    if not ended:
        obs, count, outcome = servo_translate('right', [0.12, -0.27, 1.12], 0.8, max_steps=32)
        print('clear', count, outcome)
        ended = outcome == 'ended'
    if not ended:
        for i in range(30):
            obs, reward, terminated, truncated, info = step(home)
            if terminated or truncated:
                ended = True
                break
        print('home', i + 1, info)

